export const JSONSchema202012 = [{
  namespace: 'json-schema',
  version: '2020-12'
}];
export const assoc = targetSpecs => rule => ({
  ...rule,
  targetSpecs
});
export const compose = (rules, transformer) => {
  if (typeof transformer === 'function') {
    return rules.flat(+Infinity).map(transformer);
  }
  return rules.flat();
};